from sqlglot import exp
for name in ['DateFromUnixDate','Reverse','UnixMicros','UnixMillis']:
    cls=getattr(exp,name)
    print(name, cls.arg_types)
    try:
        print(cls(this=exp.column('x')).sql(dialect='spark'))
    except Exception as e:
        print(type(e).__name__, e)
PY

